// src/engines/local-agent/local-agent-executor.ts
// LocalAgentProviderExecutor — runs one-shot agentic tasks via the opencode CLI.
// No CDP / ChromeGovernor imports (Governor Canon). v1 = one-shot `run` only.

import { EngineError } from '../../errors.js'
import type { CapabilityEventBus } from '../capability-event-bus.js'
import type { LocalAgentStore } from '../../storage/contracts/local-agent-store.js'
import type { ContentBlock } from '../../schema/streaming.js'

export const LOCAL_AGENT_SLUG = 'opencode'

export interface AgentRunInput {
  prompt: string
  model?: string
  cwd?: string
}

export interface AgentRunResult {
  blocks: ContentBlock[]
  model: string
  exitCode: number
  cost: number
  raw: string
  timedOut: boolean
}

interface OpencodeStatusLine {
  type?: string
  subtype?: string
  role?: string
  message?: { role?: string; parts?: Array<{ type?: string; text?: string }> }
  parts?: Array<{ type?: string; text?: string }>
  result?: unknown
  tokens?: { cost?: number }
  error?: string
}

/**
 * Parse the opencode `--format json` output (NDJSON status lines) into a flat
 * ContentBlock[] of assistant text. Exits with a non-zero code and an `error`
 * status emit an error block.
 */
export function parseOpencodeJson(raw: string): { blocks: ContentBlock[]; cost: number } {
  const blocks: ContentBlock[] = []
  let cost = 0
  const lines = raw.split(/\r?\n/).filter((l) => l.trim().length > 0)
  for (const line of lines) {
    let obj: OpencodeStatusLine
    try {
      obj = JSON.parse(line) as OpencodeStatusLine
    } catch {
      continue
    }
    if (typeof obj.tokens?.cost === 'number') cost = obj.tokens.cost
    const parts = obj.message?.parts ?? obj.parts
    const role = obj.message?.role ?? obj.role
    if (parts && role === 'assistant') {
      for (const part of parts) {
        if (part.type === 'text' && typeof part.text === 'string') {
          blocks.push({ type: 'text', text: part.text })
        } else if (part.type === 'step-start') {
          blocks.push({ type: 'step-start' })
        } else if (part.type === 'step-finish') {
          blocks.push({ type: 'step-finish' })
        } else if (part.type === 'reasoning' && typeof part.text === 'string') {
          blocks.push({ type: 'reasoning', text: part.text })
        }
      }
    }
    if (obj.type === 'error' || obj.subtype === 'error') {
      blocks.push({
        type: 'error',
        message: obj.error ?? 'agent run failed',
        code: 'AGENT_FAILED',
      } as ContentBlock)
    }
  }
  return { blocks, cost }
}

export class LocalAgentProviderExecutor {
  private store: LocalAgentStore
  private eventBus?: CapabilityEventBus

  constructor(store: LocalAgentStore, eventBus?: CapabilityEventBus) {
    this.store = store
    this.eventBus = eventBus
  }

  async run(input: AgentRunInput): Promise<AgentRunResult> {
    const start = Date.now()
    const provider = await this.store.getAgentProvider(LOCAL_AGENT_SLUG)
    if (!provider) {
      throw new EngineError(
        `local-agent provider '${LOCAL_AGENT_SLUG}' is not seeded`,
        'local-agent:not-seeded',
      )
    }
    const config = await this.store.getAgentConfig(LOCAL_AGENT_SLUG)
    if (!config) {
      throw new EngineError(
        `local-agent provider '${LOCAL_AGENT_SLUG}' has no config`,
        'local-agent:no-config',
      )
    }
    const model = input.model ?? config.defaultModel
    if (!(await this.store.isModelAllowed(LOCAL_AGENT_SLUG, model))) {
      throw new EngineError(
        `model '${model}' is not in the local-agent allow-list`,
        'local-agent:model-not-allowed',
      )
    }

    const args = ['run', '--auto', '--model', model, '--format', 'json', input.prompt]
    const proc = Bun.spawn([config.binary, ...args], {
      cwd: input.cwd ?? process.cwd(),
      stdout: 'pipe',
      stderr: 'pipe',
    })

    let timedOut = false
    let raw = ''
    try {
      const timeout = new Promise<'timeout'>((resolve) =>
        setTimeout(() => resolve('timeout'), config.timeoutMs),
      )
      const read = (async (): Promise<string> => {
        const out = await new Response(proc.stdout).text()
        const err = await new Response(proc.stderr).text()
        return out + (err ? `\n${err}` : '')
      })()
      const race = await Promise.race([read, timeout])
      if (race === 'timeout') {
        timedOut = true
        proc.kill()
        raw = await new Response(proc.stdout).text()
      } else {
        raw = race
      }
    } catch {
      raw = ''
    }

    const exitCode = timedOut ? -1 : (proc.exitCode ?? -1)
    const { blocks, cost } = parseOpencodeJson(raw)

    if (this.eventBus) {
      const latencyMs = Date.now() - start
      if (exitCode === 0 && !timedOut) {
        this.eventBus.emit({
          type: 'capability:executed',
          capabilityId: 'cap:agent:run',
          providerId: LOCAL_AGENT_SLUG,
          traceId: `${LOCAL_AGENT_SLUG}-${start}`,
          ok: true,
          latencyMs,
        })
      } else {
        this.eventBus.emit({
          type: 'capability:failed',
          capabilityId: 'cap:agent:run',
          providerId: LOCAL_AGENT_SLUG,
          traceId: `${LOCAL_AGENT_SLUG}-${start}`,
          error: timedOut ? 'timeout' : `exit ${exitCode}`,
          recoveryBehavior: 'retry_selector',
        })
      }
    }

    return { blocks, model, exitCode, cost, raw, timedOut }
  }
}
